/// Every element, all or nothing: if one fails, every signature object is put back as it was.
fn prepare_order_bulk_orders(req: &mut m::ApiBulkOrdersRequestInput, ctx: &PrepareContext<'_>, check: bool) -> Result<Vec<SigningRequest<'static>>> {
    let Some(elements) = req.orders.as_mut() else { return Ok(Vec::new()) };
    let saved: Vec<_> = elements.iter().map(|element| element.signature.clone()).collect();
    let mut out = Vec::with_capacity(elements.len());
    let mut failed = None;
    for element in elements.iter_mut() {
        let mut view = m::ApiCreateOrderRequestInput { order: std::mem::take(element) };
        let prepared = prepare_one_order_bulk_orders(&mut view, ctx, check);
        *element = view.order;
        match prepared {
            Ok(p) => out.push(p),
            Err(e) => {
                failed = Some(e);
                break;
            }
        }
    }
    if let Some(e) = failed {
        for (element, s) in elements.iter_mut().zip(saved) {
            element.signature = s;
        }
        return Err(e);
    }
    Ok(out)
}

