fn sig_transfer_transfer(req: &mut m::ApiTransferRequestInput) -> &mut m::SignatureInput {
    req.signature.get_or_insert_with(Default::default)
}

/// One signature object: fill, check, hash; on an error the signature object is put back as it was.
fn prepare_one_transfer_transfer(req: &mut m::ApiTransferRequestInput, ctx: &PrepareContext<'_>, check: bool) -> Result<SigningRequest<'static>> {
    let saved = req.signature.clone();
    let out = fill_and_hash_transfer_transfer(req, ctx, check);
    if out.is_err() {
        req.signature = saved;
    }
    out
}

fn fill_and_hash_transfer_transfer(req: &mut m::ApiTransferRequestInput, ctx: &PrepareContext<'_>, check: bool) -> Result<SigningRequest<'static>> {
    let sig = sig_transfer_transfer(req);
    let chain_id = w::prepare_signature(ctx, &mut sig.signer, &mut sig.nonce, &mut sig.expiration, &mut sig.chain_id, SIGNATURE_TTL_NS)?;
    let d = &*req;
    let meta = ctx.metadata;
    let _ = check;
    let currency_id = meta.currency(Some(&d.currency))?.id;
    let (from_wallet, to_wallet) = (d.from_wallet_type.as_ref(), d.to_wallet_type.as_ref());
    if from_wallet.is_none() != to_wallet.is_none() {
        return Err(Error::Signing("set both from_wallet_type and to_wallet_type, or neither".into()));
    }
    let (st, hash) = if from_wallet.is_none() {
        if currency_id > 255 {
            return Err(Error::Signing(format!("currency id {currency_id} needs from_wallet_type and to_wallet_type")));
        }
        (&*EIP712_TRANSFER, hash_transfer(d, meta)?)
    } else if currency_id <= 255 {
        (&*EIP712_TRANSFER_V2, hash_transfer_v2(d, meta)?)
    } else {
        (&*EIP712_TRANSFER_V3, hash_transfer_v3(d, meta)?)
    };
    Ok(w::signing_request(chain_id, st, hash))
}

fn typed_message_one_transfer_transfer(d: &m::ApiTransferRequestInput, meta: &Meta) -> Result<Value> {
    let currency_id = meta.currency(Some(&d.currency))?.id;
    let (from_wallet, to_wallet) = (d.from_wallet_type.as_ref(), d.to_wallet_type.as_ref());
    if from_wallet.is_none() != to_wallet.is_none() {
        return Err(Error::Signing("set both from_wallet_type and to_wallet_type, or neither".into()));
    }
    let message = if from_wallet.is_none() {
        if currency_id > 255 {
            return Err(Error::Signing(format!("currency id {currency_id} needs from_wallet_type and to_wallet_type")));
        }
        message_transfer(d, meta)?
    } else if currency_id <= 255 {
        message_transfer_v2(d, meta)?
    } else {
        message_transfer_v3(d, meta)?
    };
    Ok(message)
}

fn commit_one_transfer_transfer(req: &mut m::ApiTransferRequestInput, s: Signature) {
    let sig = sig_transfer_transfer(req);
    w::write_signature(&mut sig.signer, &mut sig.r, &mut sig.s, &mut sig.v, s);
}

